head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf70030";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.usrLdMktTpCd, pageContext.usrTpCd, page, slc_admInstTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf70030.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "div_81", attr: "__html", fn: function () { return ([String(String((dma_pageContext.get("totalSize") ?? ""))), String(String((dma_pageContext.get("pageIndex") ?? ""))), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총건수: <span>" + String(String((dma_pageContext.get("totalSize") ?? ""))) + "</span> 페이지: <span>" + String(String((dma_pageContext.get("pageIndex") ?? ""))) + "/" + String(dma_page.get("pageCount")) + "</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '1'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '2'); } }, { id: "if_usrLdMktTpCd_4", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '6'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_4", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrTpCd_4", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_page", fn: function(){ return (!(String(((dma_pageContext.get("page") ?? "")) == null ? '' : ((dma_pageContext.get("page") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchWord", fn: function () { return String(String((dma_pageContext.get("searchWord") ?? ""))); } },
        { childId: "ipt_searchFomrCd", fn: function () { return String(String((dma_pageContext.get("searchFomrCd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent('slc_admInstTpCd').setValue((String(((dma_pageContext.get("slc_admInstTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("slc_admInstTpCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("slc_admInstTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("slc_admInstTpCd") ?? "")))));
        setCommonSelect("mkTpCd");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70030.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_searchForm();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70030.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeydown
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchWord_onkeydown = async function(e){
    try {
        await scwin.keyCheck();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf70030.ipt_searchWord_onkeydown' }); }
};

/**
 * @method
 * @name input_15_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_15_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.form.submit()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70030.input_15_onclick' }); }
};

/**
 * @method
 * @name ipt_searchFomrCd_onkeydown
 * @description ipt_searchFomrCd 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchFomrCd_onkeydown = async function(e){
    try {
        await scwin.keyCheck();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf70030.ipt_searchFomrCd_onkeydown' }); }
};

/**
 * @method
 * @name grd_ReportDataList_oncellclick
 * @description grd_ReportDataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_ReportDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["integSrchYn"] === 'N') { scwin.applyIntegSrchWord(r["formcd2"], r["formKorNm"], r["ldMktTpCd"], r["formAdmInstTpCd"]); return; } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_83_onclick
 * @description krxpage_pagenavigator_83 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_83_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchFormReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_83.page' }); } await scwin.tx_searchForm(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchForm
 * @description search Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchForm = async function () {
    const sbmOptions = {
        id: "tx_searchForm",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_searchFormReq",
        target: "dlt_ReportDataList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["pageCount"] != null ? rj["pageCount"] : (rj.body && rj.body["pageCount"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_83").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_ReportDataList_fillAct
 * @description grd Report Data List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ReportDataList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.fillAct' });
    }
};

/**
 * @method
 * @name searchForm
 * @description search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchForm = async function () {
    await scwin.tx_searchForm();
    return;
};

/**
 * @method
 * @name applyIntegSrchWord
 * @description apply Integ Srch Word 처리
 * @param {String} formCd formCd
 * @param {String} formNm formNm
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} formAdmInstTpCd formAdmInstTpCd
 * @returns {void}
 * @hidden N
 */
scwin.applyIntegSrchWord = function (formCd, formNm, ldMktTpCd, formAdmInstTpCd) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame, $c.frame.Provider
    const setData = $c.win.getParent().setData(formCd, formNm, ldMktTpCd, formAdmInstTpCd);
    $c.win.closePopup();
    return;
};

/**
 * @method
 * @name keyCheck
 * @description key Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyCheck = async function () {
    if (event.keyCode === 13) {
        await scwin.searchForm();
    }
};
